#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [prefix x | middle | suffix y] -> [suffix | middle | prefix]
    vector<int> res;
    for (int i = n - y; i < n; i++) res.push_back(p[i]);       // suffix
    for (int i = x; i < n - y; i++) res.push_back(p[i]);       // middle
    for (int i = 0; i < x; i++) res.push_back(p[i]);           // prefix
    p = res;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int placed = 0; placed < n - 1; placed++) {
        // Find where element (placed+1) is
        int pos = -1;
        for (int i = placed; i < n; i++) {
            if (p[i] == placed + 1) { pos = i; break; }
        }
        if (pos == placed) continue; // already in place

        // Step 1: Move element from pos to position (n-1) if it's not already there
        if (pos != n - 1) {
            // We want to move p[pos] to the end.
            // Use x = pos+1, y = n-1-pos. This gives suffix = p[pos+1..n-1], middle = empty... 
            // x + y = pos+1 + n-1-pos = n, need x+y < n. So middle must be non-empty.
            // Use x = pos, y = n-1-pos. Then suffix = p[pos+1..n-1], middle = p[pos..pos] = {target}, prefix = p[0..pos-1]
            // Result: p[pos+1..n-1] + p[pos] + p[0..pos-1]. Target is at position n-1-pos.
            // Hmm, that doesn't put it at end either.

            // Alternative: x = pos+1, y = n-pos-1 would need middle size = n - x - y = n - pos - 1 - n + pos + 1 = 0. Not allowed.
            // Use x = 1, y = n-1-pos. Middle = p[1..pos]. Suffix = p[pos+1..n-1]. Prefix = p[0].
            // Result: p[pos+1..n-1] + p[1..pos] + p[0]. Target at position n-1-pos + (pos-1) ... complicated.

            // Simpler: move target to position 0 first. x = pos, y = 1 (if pos > 0 and pos+1 < n).
            // No wait. Let me just move target to last position:
            // x = pos+1, y picks up nothing useful... 
            // Actually: to get element at pos to end: x=pos+1, y=1, but x+y=pos+2, need pos+2<n => pos<n-2.
            // Result: p[n-1] + p[pos+1..n-2] + p[0..pos]. Target p[pos] is now at end (position n-1). Yes!
            if (pos < n - 2) {
                ops.push_back({pos + 1, 1});
                apply(p, pos + 1, 1);
                pos = n - 1;
            } else {
                // pos == n-2. x=1, y=2: result = p[n-2..n-1] + p[1..n-3] + p[0]. Target at pos 0.
                ops.push_back({1, 2});
                apply(p, 1, 2);
                for (int i = 0; i < n; i++) if (p[i] == placed+1) { pos = i; break; }
                if (pos != placed && pos != n-1 && pos < n-2) {
                    ops.push_back({pos+1, 1});
                    apply(p, pos+1, 1);
                    pos = n-1;
                }
            }
        }
        if (pos == placed) continue;
        if (pos == n - 1 && placed < n - 2) {
            // Move from end to position 'placed'. x=placed, y=1 if placed>0.
            // Result: p[n-1] + p[placed..n-2] + p[0..placed-1]. Target at position 0... not placed.
            // x = 1, y = n - placed - 1: suffix=p[placed+1..n-1], mid=p[1..placed], prefix=p[0].
            // Nah. Let me think: we want suffix to land at front, prefix at back.
            // To place target (at n-1) at position 'placed': y=1 means suffix={p[n-1]}. It goes to front (pos 0). Then prefix goes to end. So target lands at 0, not placed.
            // y=1, x=n-1-placed: suffix={p[n-1]} at pos 0, middle=p[n-1-placed..n-2], prefix=p[0..n-2-placed]. Target at 0. Not right.
            // We need target at position placed. suffix length y=1. It goes to pos 0. Not helpful unless placed=0.
            if (placed == 0) {
                ops.push_back({1, 1});
                apply(p, 1, 1);
            } else {
                // x=placed, y=n-placed-1: suffix=p[placed+1..n-1] including target at n-1. Target at position n-1-placed-1 within suffix = last in suffix = position y-1 in result = n-placed-2. Then middle=nothing(x+y=n-1, mid size=1: p[placed]). prefix=p[0..placed-1].
                // Result: p[placed+1..n-1] + p[placed] + p[0..placed-1]. Target at pos n-placed-2. Not placed.
                // Just use 2 ops: first put at pos 0, then from 0 to placed.
                ops.push_back({n-1, 1}); // x=n-1,y=1: suffix={p[n-1]}, mid=p[n-1..n-2]=empty... x+y=n. Not valid!
                // x=n-2, y=1: suffix={p[n-1]}, mid={p[n-2]}, prefix=p[0..n-3]. Result: p[n-1],p[n-2],p[0..n-3]. Target at 0.
                ops.back() = {n-2, 1};
                apply(p, n-2, 1);
                for (int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                if (pos!=placed && pos>0 && pos<n-1) {
                    ops.push_back({pos, n-pos-1});
                    apply(p, pos, n-pos-1);
                    // suffix=p[pos+1..n-1] to front, mid={}, no... mid=p[pos..pos]. Argh.
                    for (int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                }
            }
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
